let squares = [];
let maxSquares = 17;
let palettes = [['#5f0f40', '#9a031e', '#fb8b24', '#e36414', '#0f4c5c'],
								['#009F40', '#ffe5d9', '#ffcad4', '#f4acb7', '#9d8189'],
								['#335c67', '#fff3b0', '#e09f3e', '#9e2a2b', '#540b0e'],
								['#CAA719', '#dde5b6', '#adc178', '#a98467', '#6c584c'],
								['#e63946', '#D4DAD1', '#a8dadc', '#457b9d', '#1d3557']];

let palette = [];
let paletteIndex=0;

function setup() {
  createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight));

	palette = random(palettes);
	squares = [];

  for (let i = 0; i < maxSquares; i++) {
    squares.push(createRandomSquare());
  }

	strokeWeight(width/50);
}

function draw() {
  background(250);

  let now = millis();

  // Update and draw all squares
  for (let sq of squares) {
    sq.update();
    sq.draw();
  }

  // Remove squares that are done and expired
  squares = squares.filter(sq => {
    if (sq.state === 'done') {
      if (!sq.doneTime) {
        sq.doneTime = now;
      }
      return now - sq.doneTime < 5000; // keep for 5 seconds
    }
    return true;
  });

  // Add new squares if needed
  while (squares.length < maxSquares) {
    squares.push(createRandomSquare());
  }
}

function createRandomSquare() {
  let size = random(width/10, width/2);
  let speed = random(20, 100); // pixels per second
  let x = random(width/20, width - size - width/20);
  let y = random(width/20, height - size - width/20);
  let color = palette[paletteIndex];
	paletteIndex = (paletteIndex+1) % palette.length;
  return new ColoredAnimatedSquare(x, y, size, speed, color);
}


class AnimatedSquare {
  constructor(x, y, size, speed) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.speed = speed; // pixels per second
    this.state = 'drawing';
    this.strokeIndex = 0;
    this.strokeProgress = 0;
    this.lastUpdateTime = millis();
    this.points = [];
    this.generateSquigglyEdges();
  }

  generateSquigglyEdges() {
    const squiggle = (x1, y1, x2, y2, segments = random(20,200), amplitude = random(0.5,3)) => {
      let pts = [];
      for (let i = 0; i <= segments; i++) {
        let t = i / segments;
        let x = lerp(x1, x2, t);
        let y = lerp(y1, y2, t);
        let offset = sin(t * PI * 4) * amplitude;
        let angle = atan2(y2 - y1, x2 - x1) + HALF_PI;
        x += cos(angle) * offset;
        y += sin(angle) * offset;
        pts.push(createVector(x, y));
      }
      return pts;
    };

    let corners = [
      [this.x, this.y],
      [this.x + this.size, this.y],
      [this.x + this.size, this.y + this.size],
      [this.x, this.y + this.size],
      [this.x, this.y] // closing the square
    ];

    for (let i = 0; i < 4; i++) {
      let [x1, y1] = corners[i];
      let [x2, y2] = corners[i + 1];
      this.points.push(squiggle(x1, y1, x2, y2));
    }
  }

  update() {
    if (this.state === 'done') return;

    let now = millis();
    let deltaTime = (now - this.lastUpdateTime) / 1000.0;
    this.lastUpdateTime = now;

    let currentStroke = this.points[this.strokeIndex];
    this.strokeProgress += this.speed * deltaTime;

    if (this.strokeProgress >= currentStroke.length) {
      this.strokeIndex++;
      this.strokeProgress = 0;
      if (this.strokeIndex >= this.points.length) {
        this.state = 'done';
      }
    }
  }

  draw() {
    stroke(0);
    noFill();

    for (let i = 0; i < this.strokeIndex; i++) {
      beginShape();
      for (let pt of this.points[i]) {
        vertex(pt.x, pt.y);
      }
      endShape();
    }

    if (this.state !== 'done') {
      let currentStroke = this.points[this.strokeIndex];
      let maxIndex = floor(this.strokeProgress);
      beginShape();
      for (let i = 0; i <= maxIndex && i < currentStroke.length; i++) {
        vertex(currentStroke[i].x, currentStroke[i].y);
      }
      endShape();
    }
  }
}

class ColoredAnimatedSquare extends AnimatedSquare {
  constructor(x, y, size, speed, color) {
    super(x, y, size, speed);
    this.color = color;
    this.doneTime = null;
    this.alpha = alpha(this.color);
  }

  update() {
    super.update();

    if (this.state === 'done') {
      if (!this.doneTime) {
        this.doneTime = millis();
      } else {
        let elapsed = millis() - this.doneTime;
        this.alpha = map(elapsed, 0, 5000, alpha(this.color), 0);
        this.alpha = constrain(this.alpha, 0, 255);
      }
    }
  }

  draw() {
    let c = color(this.color);
    c.setAlpha(this.alpha);
    stroke(c);
    noFill();

    for (let i = 0; i < this.strokeIndex; i++) {
      beginShape();
      for (let pt of this.points[i]) {
        vertex(pt.x, pt.y);
      }
      endShape();
    }

    if (this.state !== 'done') {
      let currentStroke = this.points[this.strokeIndex];
      let maxIndex = floor(this.strokeProgress);
      beginShape();
      for (let i = 0; i <= maxIndex && i < currentStroke.length; i++) {
        vertex(currentStroke[i].x, currentStroke[i].y);
      }
      endShape();
    }
  }
}

